        state, _ = await self._snapshot()
        return {branch: state["heads"][branch] for branch in branches}

    async def get_status(self, bundle):
        state, _ = await self._snapshot()
        b = state["bundles"][bundle]
        return {"revision": b["revision"], "updates": copy.deepcopy(b["updates"]),
