  start state Init {
    entry {
      announce eApproval, (reviewer = 0,);
      announce eApproval, (reviewer = 1,);
      announce eCI, (passed = true,);
      announce ePublish, (expected = 0, proposed = 1,);
      goto Done;
    }
  }
  state Done {}
}

